import { sha256 } from '../../core/receipt.f26cc58af58e.mjs';
export function createPermissionCard(input={}){if(!input.id||!input.action)throw new Error('permission id and action are required');if(!Array.isArray(input.scope)||!input.scope.length)throw new Error('permission scope is required');if(!input.expiresAt||Number.isNaN(Date.parse(input.expiresAt)))throw new Error('permission expiry is required');const allowed=new Set(['allow-once','allow-project','deny']);return Object.freeze({decide(decision){if(!allowed.has(decision))throw new Error('Unknown permission decision');const base={schema:'nolane.ui.permission-decision.v1',id:String(input.id),decision,action:String(input.action),scope:input.scope.map(String),expiresAt:String(input.expiresAt)};return Object.freeze({...base,receiptSha256:sha256(JSON.stringify(base))})}})}
